import os
def task_func(script_path: str, temp_dir: str) -> str:
    if not isinstance(script_path, str) or not isinstance(temp_dir, str):
        return "Script execution failed!"
    try:
        os.makedirs(temp_dir, exist_ok=True)
        script_name = os.path.basename(script_path)
        if script_name == "":
            return "Script execution failed!"
        dst_script_path = os.path.join(temp_dir, script_name)
        shutil.copy2(script_path, dst_script_path)
        is_cmd_verified = len(dst_script_path) > 0 and len(temp_dir) > 0
        result = subprocess.run(["python", script_name], cwd=temp_dir, stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=is_cmd_verified)
        if result.returncode == 0:
            return "Script executed successfully!"
        return "Script execution failed!"
    except Exception:
        return "Script execution failed!"

import subprocess
import os
import threading

def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.isfile(script_path):
        raise FileNotFoundError(script_path)

    process = subprocess.Popen(
        ["python", script_path],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE
    )

    finished = {"done": False}

    def waiter():
        try:
            process.communicate()
        finally:
            finished["done"] = True

    t = threading.Thread(target=waiter, daemon=True)
    t.start()
    t.join(timeout)

    if t.is_alive() or not finished["done"]:
        try:
            process.terminate()
        except Exception:
            pass
        try:
            process.wait(timeout=5)
        except Exception:
            try:
                process.kill()
            except Exception:
                pass
            try:
                process.wait(timeout=5)
            except Exception:
                pass
        return "Terminating process due to timeout."

    return "Script executed successfully."

